import { useAuth } from "@/_core/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Progress } from "@/components/ui/progress";
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { startLogin } from "@/const";
import { trpc } from "@/lib/trpc";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import {
  BarChart3, CalendarDays, Check, ChevronDown, CircleHelp, Clock3, FileText, Flag, FolderKanban,
  LayoutDashboard, ListChecks, Menu, MoreHorizontal, Plus, Presentation, Search, Settings,
  Target, TrendingUp, Users, X, ArrowRight, AlertTriangle, ChevronLeft, UserRound,
} from "lucide-react";
import { useMemo, useState } from "react";
import { Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

type Page = "home" | "plan" | "time" | "projects" | "project" | "tasks" | "team" | "member" | "calendar" | "reports" | "settings";
type Period = "day" | "week" | "month" | "quarter" | "year";
type TaskStatus = "not_started" | "in_progress" | "in_review" | "complete" | "overdue";
type ProjectStatus = "planned" | "in_progress" | "in_review" | "complete" | "blocked";

const periodLabels: Record<Period, string> = { day: "اليوم", week: "هذا الأسبوع", month: "أغسطس 2026", quarter: "الربع الثالث 2026", year: "الخطة السنوية 2026" };
const taskStatusLabel: Record<string, string> = { not_started: "لم تبدأ", in_progress: "قيد التنفيذ", in_review: "للمراجعة", complete: "مكتملة", overdue: "متأخرة" };
const projectStatusLabel: Record<string, string> = { planned: "مخطط", in_progress: "قيد التنفيذ", in_review: "للمراجعة", complete: "مكتمل", blocked: "متعثر" };
const priorityLabel: Record<string, string> = { urgent: "عاجلة", high: "عالية", medium: "متوسطة", low: "منخفضة" };

function dateText(value: Date | string | null | undefined, short = true) {
  if (!value) return "—";
  return new Intl.DateTimeFormat("ar-SA", { day: "numeric", month: short ? "short" : "long" }).format(new Date(value));
}

function statusClass(status: string) {
  if (status === "complete" || status === "on_track") return "bg-emerald-50 text-emerald-700 ring-emerald-100";
  if (status === "overdue" || status === "blocked" || status === "at_risk") return "bg-rose-50 text-rose-700 ring-rose-100";
  if (status === "in_review" || status === "attention") return "bg-amber-50 text-amber-700 ring-amber-100";
  return "bg-slate-100 text-slate-600 ring-slate-200";
}

function StatusPill({ status, project = false }: { status: string; project?: boolean }) {
  return <span className={cn("inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-medium ring-1 ring-inset whitespace-nowrap", statusClass(status))}>{project ? projectStatusLabel[status] : taskStatusLabel[status] ?? status}</span>;
}

function Avatar({ initials, color, className }: { initials: string; color?: string; className?: string }) {
  return <span className={cn("flex shrink-0 items-center justify-center rounded-full text-xs font-semibold text-white", className)} style={{ backgroundColor: color ?? "#6C8FB8" }}>{initials}</span>;
}

function PeriodSelect({ value, onChange }: { value: Period; onChange: (value: Period) => void }) {
  return <label className="relative inline-flex items-center">
    <select value={value} onChange={(e) => onChange(e.target.value as Period)} className="appearance-none rounded-lg border border-slate-200 bg-white py-2 pr-3 pl-8 text-sm font-medium text-[#52657A] outline-none transition focus:border-[#6C8FB8] focus:ring-2 focus:ring-[#6C8FB8]/10">
      <option value="day">اليوم</option><option value="week">الأسبوع</option><option value="month">الشهر</option><option value="quarter">الربع</option><option value="year">السنة</option>
    </select>
    <ChevronDown className="pointer-events-none absolute left-2.5 size-4 text-slate-400" />
  </label>;
}

function SectionTitle({ children, action }: { children: React.ReactNode; action?: React.ReactNode }) {
  return <div className="mb-4 flex items-center justify-between"><h2 className="text-sm font-semibold text-[#26364A]">{children}</h2>{action}</div>;
}

function EmptyState({ title }: { title: string }) { return <div className="py-12 text-center text-sm text-slate-500">{title}</div>; }

export default function Home() {
  const { user } = useAuth();
  const utils = trpc.useUtils();
  const { data, isLoading, error } = trpc.workspace.overview.useQuery(undefined, { staleTime: 30_000 });
  const updateTask = trpc.workspace.updateTaskStatus.useMutation({ onSuccess: () => { utils.workspace.overview.invalidate(); toast.success("تم تحديث حالة المهمة"); } });
  const createTask = trpc.workspace.createTask.useMutation({ onSuccess: (result) => { utils.workspace.overview.invalidate(); toast.success("تمت إضافة المهمة"); if (result.showLoadWarning) toast.warning("هذا العضو لديه عبء عمل مرتفع حاليًا."); } });
  const createProject = trpc.workspace.createProject.useMutation({ onSuccess: () => { utils.workspace.overview.invalidate(); toast.success("تم إنشاء المشروع"); } });
  const [page, setPage] = useState<Page>("home");
  const [period, setPeriod] = useState<Period>("week");
  const [projectId, setProjectId] = useState<number | null>(null);
  const [memberId, setMemberId] = useState<number | null>(null);
  const [showNav, setShowNav] = useState(false);
  const [presentation, setPresentation] = useState(false);
  const [taskDrawer, setTaskDrawer] = useState(false);
  const [projectDrawer, setProjectDrawer] = useState(false);

  const goPeriod = (next: Period) => { setPeriod(next); setPage(next === "year" ? "plan" : "time"); };
  const requireManager = (action: () => void) => { if (!user) { toast.message("سجّل الدخول لإدارة أعمال القسم"); startLogin(); return; } action(); };
  const completeTask = (id: number) => { if (!user) { toast.message("سجّل الدخول لتحديث حالة المهمة"); startLogin(); return; } updateTask.mutate({ id, status: "complete" }); };

  if (presentation && data) return <PresentationMode data={data} period={period} close={() => setPresentation(false)} />;
  if (isLoading) return <LoadingShell />;
  if (error || !data) return <div dir="rtl" className="flex min-h-screen items-center justify-center bg-[#F7F9FC] p-8 text-center"><div><AlertTriangle className="mx-auto mb-3 size-7 text-amber-600" /><h1 className="font-semibold">تعذر تحميل لوحة القسم</h1><p className="mt-2 text-sm text-slate-500">يرجى تحديث الصفحة أو المحاولة لاحقًا.</p></div></div>;

  const shared = { data, user, setPage, setProjectId, setMemberId, period, goPeriod, completeTask, openTask: () => requireManager(() => setTaskDrawer(true)), openProject: () => requireManager(() => setProjectDrawer(true)) };
  return <div dir="rtl" className="min-h-screen bg-[#F7F9FC] text-[#26364A]">
    <Sidebar page={page} onNavigate={(next) => { setPage(next); setShowNav(false); }} open={showNav} close={() => setShowNav(false)} />
    <main className="min-h-screen px-4 py-5 lg:mr-[272px] lg:px-9 lg:py-8">
      <header className="mb-8 flex items-center justify-between gap-4">
        <div className="flex items-center gap-3 lg:hidden"><button onClick={() => setShowNav(true)} aria-label="فتح القائمة" className="rounded-lg border border-slate-200 bg-white p-2 text-slate-600"><Menu className="size-5" /></button><span className="font-semibold text-[#52769F]">تشغيل</span></div>
        <div className="hidden lg:block"><p className="text-xs font-medium text-[#7C8A9A]">قسم الاستراتيجية والتطوير</p><p className="mt-1 text-sm text-[#52657A]">الأربعاء، ٢٦ أغسطس ٢٠٢٦</p></div>
        <div className="mr-auto flex items-center gap-2"><PeriodSelect value={period} onChange={goPeriod} /><Button variant="outline" onClick={() => setPresentation(true)} className="hidden h-9 gap-2 border-slate-200 bg-white px-3 text-xs text-[#52657A] md:inline-flex"><Presentation className="size-4" />وضع العرض</Button></div>
      </header>
      {page === "home" && <OverviewPage {...shared} />}
      {page === "plan" && <AnnualPlanPage {...shared} />}
      {page === "time" && <TemporalPage {...shared} />}
      {page === "projects" && <ProjectsPage {...shared} />}
      {page === "project" && <ProjectDetail {...shared} projectId={projectId} />}
      {page === "tasks" && <TasksPage {...shared} />}
      {page === "team" && <TeamPage {...shared} />}
      {page === "member" && <MemberDetail {...shared} memberId={memberId} />}
      {page === "calendar" && <CalendarPage {...shared} />}
      {page === "reports" && <ReportsPage {...shared} />}
      {page === "settings" && <SettingsPage />}
    </main>
    <TaskDrawer open={taskDrawer} setOpen={setTaskDrawer} data={data} submitting={createTask.isPending} onSubmit={(input: any) => createTask.mutate(input)} />
    <ProjectDrawer open={projectDrawer} setOpen={setProjectDrawer} data={data} submitting={createProject.isPending} onSubmit={(input: any) => createProject.mutate(input)} />
  </div>;
}

function Sidebar({ page, onNavigate, open, close }: { page: Page; onNavigate: (page: Page) => void; open: boolean; close: () => void }) {
  const entries: { id: Page; label: string; icon: typeof LayoutDashboard }[] = [
    { id: "home", label: "الرئيسية", icon: LayoutDashboard }, { id: "plan", label: "الخطة السنوية", icon: Target },
    { id: "projects", label: "المشاريع", icon: FolderKanban }, { id: "tasks", label: "المهام", icon: ListChecks },
    { id: "team", label: "الفريق", icon: Users }, { id: "calendar", label: "التقويم", icon: CalendarDays }, { id: "reports", label: "التقارير", icon: BarChart3 },
  ];
  return <><div onClick={close} className={cn("fixed inset-0 z-40 bg-slate-900/20 backdrop-blur-[1px] lg:hidden", open ? "block" : "hidden")} />
    <aside className={cn("fixed inset-y-0 right-0 z-50 flex w-[272px] flex-col border-l border-slate-200 bg-white px-4 py-6 transition-transform duration-200 lg:translate-x-0", open ? "translate-x-0" : "translate-x-full") }>
      <div className="mb-10 flex items-center justify-between px-2"><div className="flex items-center gap-3"><span className="flex size-9 items-center justify-center rounded-xl bg-[#EDF4FA] text-[#52769F]"><Target className="size-5" /></span><div><p className="text-sm font-bold tracking-tight text-[#26364A]">تشغيل</p><p className="text-[11px] text-[#7C8A9A]">لوحة أعمال القسم</p></div></div><button onClick={close} className="lg:hidden"><X className="size-5 text-slate-400" /></button></div>
      <nav className="space-y-1">{entries.map((entry) => { const active = page === entry.id || (entry.id === "plan" && page === "time"); return <button key={entry.id} onClick={() => onNavigate(entry.id)} className={cn("flex h-11 w-full items-center gap-3 rounded-lg px-3 text-right text-sm transition-colors", active ? "bg-[#EDF4FA] font-semibold text-[#52769F]" : "text-[#647487] hover:bg-slate-50 hover:text-[#52657A]")}><entry.icon className="size-[18px]" />{entry.label}</button>; })}</nav>
      <div className="mt-auto border-t border-slate-100 pt-4"><button onClick={() => onNavigate("settings")} className={cn("flex h-11 w-full items-center gap-3 rounded-lg px-3 text-sm", page === "settings" ? "bg-[#EDF4FA] font-semibold text-[#52769F]" : "text-[#647487] hover:bg-slate-50")}><Settings className="size-[18px]" />الإعدادات</button><div className="mt-5 flex items-center gap-2 px-3"><Avatar initials="سح" color="#52769F" className="size-8" /><div className="min-w-0"><p className="truncate text-xs font-semibold">سارة الحربي</p><p className="text-[10px] text-[#7C8A9A]">مديرة القسم</p></div></div></div>
    </aside></>;
}

function PageHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <p className="mb-2 text-xs font-semibold text-[#6C8FB8]">{eyebrow}</p>}<h1 className="text-2xl font-bold tracking-tight text-[#26364A] md:text-[28px]">{title}</h1>{description && <p className="mt-2 text-sm text-[#7C8A9A]">{description}</p>}</div>{action}</div>; }

function OverviewPage({ data, setPage, setProjectId, period, openTask, completeTask }: any) {
  const attention = [
    ...data.tasks.filter((task: any) => task.status === "overdue" || task.isApprovalPending).map((task: any) => ({ type: "task", title: task.title, id: task.id, due: task.dueDate, status: task.status, assignee: data.members.find((member: any) => member.id === task.assigneeMemberId) })),
    ...data.projects.filter((project: any) => project.status === "blocked").map((project: any) => ({ type: "project", title: project.title, id: project.id, due: project.endDate, status: project.status, assignee: data.members.find((member: any) => member.id === project.ownerMemberId) })),
  ].slice(0, 4);
  const priorities = data.tasks.filter((task: any) => task.status !== "complete").sort((a: any, b: any) => (a.dueDate ? new Date(a.dueDate).getTime() : Infinity) - (b.dueDate ? new Date(b.dueDate).getTime() : Infinity)).slice(0, 5);
  const completion = Math.round((data.tasks.filter((task: any) => task.status === "complete").length / data.tasks.length) * 100);
  return <div className="entry max-w-5xl"><PageHeading eyebrow={periodLabels[period as Period]} title="وش يحتاج انتباهي الآن؟" description="نظرة مركزة على ما يحتاج قرارًا أو متابعة في هذه الفترة." action={<Button onClick={openTask} className="h-10 gap-2 bg-[#52769F] px-4 hover:bg-[#46698F]"><Plus className="size-4" />مهمة جديدة</Button>} />
    <div className="mb-9 max-w-xl rounded-xl border border-[#E8EEF5] bg-white px-5 py-4"><div className="mb-3 flex items-center justify-between"><span className="text-sm font-semibold">إنجاز الأسبوع</span><span className="text-sm font-bold text-[#52769F]">{completion}%</span></div><Progress value={completion} className="h-2 bg-[#EDF4FA] [&>div]:bg-[#6C8FB8]" /></div>
    <div className="grid gap-5 lg:grid-cols-[1fr_.92fr]"><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle action={<span className="text-xs text-[#7C8A9A]">{attention.length} عناصر</span>}>يحتاج انتباهك</SectionTitle><div className="divide-y divide-slate-100">{attention.length ? attention.map((item: any) => <button key={`${item.type}-${item.id}`} onClick={() => { if (item.type === "project") { setProjectId(item.id); setPage("project"); } else setPage("tasks"); }} className="flex w-full items-center gap-3 py-3 text-right transition hover:bg-slate-50"><span className={cn("size-2 rounded-full", item.status === "overdue" || item.status === "blocked" ? "bg-rose-500" : "bg-amber-500")} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{item.title}</p><p className="mt-1 text-xs text-[#7C8A9A]">{item.assignee?.name ?? "غير مسند"} · {item.status === "overdue" ? "متأخر" : item.status === "blocked" ? "متعثر" : "بانتظار اعتماد"}</p></div><span className="text-xs text-[#7C8A9A]">{dateText(item.due)}</span></button>) : <EmptyState title="لا توجد عناصر حرجة الآن" />}</div></section>
      <section className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle action={<button onClick={() => setPage("tasks")} className="text-xs font-medium text-[#52769F]">عرض الكل</button>}>أولويات هذا الأسبوع</SectionTitle><div className="space-y-2">{priorities.map((task: any) => { const member = data.members.find((item: any) => item.id === task.assigneeMemberId); return <div key={task.id} className="flex items-center gap-3 rounded-lg px-1 py-2"><button onClick={() => completeTask(task.id)} className={cn("flex size-5 shrink-0 items-center justify-center rounded-md border transition", task.status === "complete" ? "border-emerald-500 bg-emerald-500 text-white" : "border-slate-300 text-transparent hover:border-[#6C8FB8]")}><Check className="size-3" /></button><div className="min-w-0 flex-1"><p className={cn("truncate text-sm", task.status === "complete" && "text-slate-400 line-through")}>{task.title}</p><p className="mt-0.5 text-[11px] text-[#7C8A9A]">{member?.name ?? "غير مسند"} · {dateText(task.dueDate)}</p></div><StatusPill status={task.status} /></div>; })}</div></section></div>
    <div className="mt-5 rounded-xl border border-[#E5ECF3] bg-[#FDFEFF] px-5 py-4"><div className="flex items-center gap-3"><Clock3 className="size-4 text-[#6C8FB8]" /><p className="text-sm text-[#52657A]"><strong className="font-semibold text-[#26364A]">القادم:</strong> إطلاق النسخة التجريبية للبوابة الرقمية خلال أسبوعين.</p></div></div>
  </div>;
}

function AnnualPlanPage({ data, setPage, period, goPeriod }: any) {
  const quarters = [{ q: "Q1", theme: "تأسيس الأولويات", progress: 100 }, { q: "Q2", theme: "بناء الحلول", progress: 88 }, { q: "Q3", theme: "التنفيذ والتسليم", progress: 67 }, { q: "Q4", theme: "قياس الأثر", progress: 0 }];
  const planProgress = Math.round(data.goals.reduce((sum: number, goal: any) => sum + goal.progress, 0) / data.goals.length);
  return <div className="entry max-w-5xl"><PageHeading eyebrow="السنة" title="الخطة السنوية 2026" description="هل نحن ماشيين حسب الخطة؟" action={<PeriodSelect value={period} onChange={goPeriod} />} />
    <section className="mb-8 max-w-xl rounded-xl border border-slate-200 bg-white p-5"><div className="mb-3 flex items-center justify-between"><span className="text-sm font-semibold">إنجاز الخطة</span><span className="font-bold text-[#52769F]">{planProgress}%</span></div><Progress value={planProgress} className="h-2 bg-[#EDF4FA] [&>div]:bg-[#6C8FB8]" /></section>
    <section className="mb-8 rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>خارطة السنة</SectionTitle><div className="grid gap-4 md:grid-cols-4">{quarters.map((quarter, index) => <button key={quarter.q} onClick={() => { if (index === 2) { goPeriod("quarter"); setPage("time"); } }} className="group rounded-lg border border-slate-100 p-4 text-right transition hover:border-[#C9DBEC] hover:bg-[#FAFCFE]"><div className="mb-5 flex items-center justify-between"><span className="text-xs font-bold tracking-wide text-[#6C8FB8]">{quarter.q}</span><span className="text-xs font-semibold text-[#52657A]">{quarter.progress}%</span></div><p className="text-sm font-medium">{quarter.theme}</p><div className="mt-4 h-1 overflow-hidden rounded-full bg-slate-100"><div className="h-full bg-[#6C8FB8]" style={{ width: `${quarter.progress}%` }} /></div></button>)}</div></section>
    <section className="max-w-3xl rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>أهم أهداف السنة</SectionTitle><div className="divide-y divide-slate-100">{data.goals.map((goal: any) => <div key={goal.id} className="flex items-center gap-4 py-3"><div className="min-w-0 flex-1"><p className="text-sm font-medium">{goal.title}</p><p className="mt-1 text-xs text-[#7C8A9A]">{goal.theme}</p></div><span className="text-sm font-semibold text-[#52657A]">{goal.progress}%</span><div className="w-20"><Progress value={goal.progress} className="h-1.5 bg-slate-100 [&>div]:bg-[#6C8FB8]" /></div></div>)}</div><button className="mt-4 text-sm font-medium text-amber-700"><AlertTriangle className="ml-1 inline size-4" />٢ مخاطر تحتاج متابعة</button></section>
  </div>;
}

function TemporalPage({ data, period, goPeriod, setPage, setProjectId, completeTask }: any) {
  const upcoming = data.tasks.filter((task: any) => task.status !== "complete").sort((a: any, b: any) => new Date(a.dueDate ?? 0).getTime() - new Date(b.dueDate ?? 0).getTime());
  const taskRows = period === "day" ? upcoming.filter((task: any) => dateText(task.dueDate) === dateText(new Date("2026-08-26"))).slice(0, 5) : upcoming.slice(0, 5);
  const heading = period === "quarter" ? "وش أهم شيء لازم ننجزه هذا الربع؟" : period === "month" ? "وش أهم التسليمات هذا الشهر؟" : period === "day" ? "وش لازم يخلص اليوم؟" : "وش لازم يخلص هذا الأسبوع؟";
  const label = period === "day" ? "اليوم — الأربعاء ٢٦ أغسطس" : periodLabels[period as Period];
  const completion = period === "quarter" ? 61 : period === "month" ? 64 : period === "day" ? 40 : 67;
  if (period === "month") return <MonthView data={data} period={period} goPeriod={goPeriod} />;
  return <div className="entry max-w-5xl"><PageHeading eyebrow={label} title={heading} action={<PeriodSelect value={period} onChange={goPeriod} />} />
    {period === "day" && <div className="mb-5 inline-flex items-center gap-2 rounded-lg border border-rose-100 bg-rose-50 px-3 py-2 text-xs font-medium text-rose-700"><AlertTriangle className="size-4" />١ مهمة متأخرة</div>}
    <section className="mb-6 max-w-xl rounded-xl border border-slate-200 bg-white p-5"><div className="mb-3 flex justify-between text-sm"><span className="font-semibold">إنجاز {period === "quarter" ? "الربع" : period === "day" ? "اليوم" : "الأسبوع"}</span><strong className="text-[#52769F]">{completion}%</strong></div><Progress value={completion} className="h-2 bg-[#EDF4FA] [&>div]:bg-[#6C8FB8]" /></section>
    <div className="grid gap-5 lg:grid-cols-[1fr_.65fr]"><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>{period === "quarter" ? "أولويات الربع" : period === "day" ? "مهام اليوم" : "أولويات الأسبوع"}</SectionTitle><div className="divide-y divide-slate-100">{taskRows.map((task: any) => { const member = data.members.find((item: any) => item.id === task.assigneeMemberId); return <div key={task.id} className="flex items-center gap-3 py-3"><button onClick={() => completeTask(task.id)} className="flex size-5 items-center justify-center rounded-md border border-slate-300 text-transparent hover:border-[#6C8FB8]"><Check className="size-3" /></button><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{task.title}</p><p className="mt-1 text-xs text-[#7C8A9A]">{member?.name} · {dateText(task.dueDate)}</p></div><StatusPill status={task.status} /></div>; })}</div></section>
      <section className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>{period === "quarter" ? "المعالم القادمة" : "القادم"}</SectionTitle><div className="space-y-4">{data.events.slice(0, 3).map((event: any) => <div key={event.id} className="flex items-start gap-3"><div className="mt-1 h-2 w-2 rounded-full bg-[#6C8FB8]" /><div><p className="text-sm font-medium">{event.title}</p><p className="mt-1 text-xs text-[#7C8A9A]">{dateText(event.eventDate, false)}</p></div></div>)}</div></section></div>
  </div>;
}

function MonthView({ data, period, goPeriod }: any) {
  const weeks = ["الأسبوع ١", "الأسبوع ٢", "الأسبوع ٣", "الأسبوع ٤"];
  const mainDeliveries = data.events.filter((event: any) => event.type !== "meeting").slice(0, 4);
  return <div className="entry max-w-5xl"><PageHeading eyebrow="الشهر" title="أغسطس ٢٠٢٦" description="وش أهم التسليمات هذا الشهر؟" action={<PeriodSelect value={period} onChange={goPeriod} />} /><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>تسليمات الشهر</SectionTitle><div className="grid gap-3 md:grid-cols-4">{weeks.map((week, index) => <div key={week} className="min-h-36 rounded-lg border border-slate-100 bg-[#FCFDFE] p-3"><p className="mb-4 text-xs font-semibold text-[#7C8A9A]">{week}</p>{mainDeliveries[index] && <div className="rounded-md border-r-2 border-[#6C8FB8] bg-[#EDF4FA]/60 px-2 py-2 text-xs leading-5 text-[#3E5C7D]">{mainDeliveries[index].title}<span className="mt-1 block text-[10px] text-[#7C8A9A]">{dateText(mainDeliveries[index].eventDate)}</span></div>}</div>)}</div></section><section className="mt-5 max-w-2xl rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>يحتاج انتباه هذا الشهر</SectionTitle>{data.projects.filter((project: any) => project.status === "blocked" || project.progress < 45).slice(0, 3).map((project: any) => <div key={project.id} className="flex items-center justify-between py-2"><span className="text-sm">{project.title}</span><StatusPill status={project.status} project /></div>)}</section></div>;
}

function ProjectsPage({ data, setPage, setProjectId, openProject }: any) {
  const [query, setQuery] = useState(""); const [status, setStatus] = useState("all");
  const projects = data.projects.filter((project: any) => project.title.includes(query) && (status === "all" || project.status === status));
  return <div className="entry"><PageHeading title="المشاريع" description="وين وصل كل مشروع؟" action={<Button onClick={openProject} className="h-10 gap-2 bg-[#52769F] hover:bg-[#46698F]"><Plus className="size-4" />مشروع جديد</Button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative max-w-sm flex-1"><Search className="absolute right-3 top-2.5 size-4 text-slate-400" /><Input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="ابحث عن مشروع" className="h-9 border-slate-200 bg-white pr-9" /></div><select value={status} onChange={(e) => setStatus(e.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-sm text-[#52657A]"><option value="all">كل الحالات</option>{Object.entries(projectStatusLabel).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div><div className="overflow-hidden rounded-xl border border-slate-200 bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-right"><thead className="border-b border-slate-100 bg-[#FCFDFE] text-[11px] font-medium text-[#7C8A9A]"><tr><th className="px-5 py-3.5">المشروع</th><th className="px-5 py-3.5">المسؤول</th><th className="px-5 py-3.5">الحالة</th><th className="px-5 py-3.5">التقدم</th><th className="px-5 py-3.5">الموعد</th><th /></tr></thead><tbody>{projects.map((project: any) => { const owner = data.members.find((member: any) => member.id === project.ownerMemberId); return <tr key={project.id} onClick={() => { setProjectId(project.id); setPage("project"); }} className="cursor-pointer border-b border-slate-100 last:border-0 hover:bg-[#FBFCFE]"><td className="px-5 py-4"><p className="text-sm font-medium">{project.title}</p><p className="mt-1 max-w-60 truncate text-xs text-[#7C8A9A]">{project.summary}</p></td><td className="px-5 py-4"><div className="flex items-center gap-2"><Avatar initials={owner?.avatarInitials ?? "—"} color={owner?.color} className="size-6 text-[9px]" /><span className="text-xs">{owner?.name}</span></div></td><td className="px-5 py-4"><StatusPill status={project.status} project /></td><td className="px-5 py-4"><div className="flex items-center gap-2"><span className="text-xs text-[#52657A]">{project.progress}%</span><Progress value={project.progress} className="h-1.5 w-16 bg-slate-100 [&>div]:bg-[#6C8FB8]" /></div></td><td className="px-5 py-4 text-xs text-[#7C8A9A]">{dateText(project.endDate)}</td><td className="px-5 py-4"><ChevronLeft className="size-4 text-slate-400" /></td></tr>; })}</tbody></table></div></div></div>;
}

function ProjectDetail({ data, projectId, setPage, openTask }: any) {
  const project = data.projects.find((item: any) => item.id === projectId) ?? data.projects[0]; const owner = data.members.find((member: any) => member.id === project.ownerMemberId);
  const outputs = data.deliverables.filter((item: any) => item.projectId === project.id); const linkedTasks = data.tasks.filter((item: any) => item.projectId === project.id);
  const [tab, setTab] = useState("work");
  return <div className="entry max-w-5xl"><button onClick={() => setPage("projects")} className="mb-5 flex items-center gap-1 text-sm text-[#647487] hover:text-[#52769F]"><ArrowRight className="size-4" />كل المشاريع</button><div className="flex flex-col justify-between gap-4 border-b border-slate-200 pb-6 md:flex-row md:items-start"><div><p className="mb-2 text-xs font-semibold text-[#6C8FB8]">مشروع</p><h1 className="text-2xl font-bold">{project.title}</h1><p className="mt-2 max-w-xl text-sm leading-6 text-[#7C8A9A]">{project.summary}</p></div><Button onClick={openTask} className="h-9 gap-2 bg-[#52769F] hover:bg-[#46698F]"><Plus className="size-4" />إضافة مهمة</Button></div><div className="mt-5 flex flex-wrap items-center gap-x-7 gap-y-3 text-sm"><div className="flex items-center gap-2"><Avatar initials={owner?.avatarInitials ?? "—"} color={owner?.color} className="size-7 text-[10px]" /><span>{owner?.name}</span></div><span className="text-[#7C8A9A]">الموعد: <b className="mr-1 font-medium text-[#52657A]">{dateText(project.endDate, false)}</b></span><span className="text-[#7C8A9A]">التقدم: <b className="mr-1 font-medium text-[#52657A]">{project.progress}%</b></span><StatusPill status={project.status} project /></div><div className="mt-8 flex gap-5 border-b border-slate-200"><button onClick={() => setTab("work")} className={cn("border-b-2 px-1 pb-3 text-sm", tab === "work" ? "border-[#6C8FB8] font-semibold text-[#52769F]" : "border-transparent text-[#7C8A9A]")}>العمل</button><button onClick={() => setTab("activity")} className={cn("border-b-2 px-1 pb-3 text-sm", tab === "activity" ? "border-[#6C8FB8] font-semibold text-[#52769F]" : "border-transparent text-[#7C8A9A]")}>النشاط والملفات</button></div>{tab === "work" ? <div className="mt-6 grid gap-5 lg:grid-cols-2"><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>المخرجات</SectionTitle><div className="space-y-1">{outputs.map((output: any) => <div key={output.id} className="flex items-center gap-3 rounded-lg py-2.5"><span className={cn("flex size-5 items-center justify-center rounded-full", output.status === "complete" ? "bg-emerald-100 text-emerald-700" : "bg-slate-100 text-slate-400")}><Check className="size-3" /></span><div className="min-w-0 flex-1"><p className="text-sm">{output.title}</p><p className="text-[11px] text-[#7C8A9A]">{dateText(output.dueDate)}</p></div><span className="text-xs text-[#52657A]">{output.progress}%</span></div>)}</div></section><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>المهام</SectionTitle><div className="space-y-1">{linkedTasks.slice(0, 6).map((task: any) => <div key={task.id} className="flex items-center justify-between py-2.5"><p className="text-sm">{task.title}</p><StatusPill status={task.status} /></div>)}</div></section></div> : <div className="mt-6 rounded-xl border border-dashed border-slate-300 bg-white p-8 text-center text-sm text-[#7C8A9A]">تظهر هنا الملفات والتعليقات والنشاط المرتبط بالمشروع عند إضافتها.</div>}</div>;
}

function TasksPage({ data, openTask, completeTask }: any) { const [query, setQuery] = useState(""); const [state, setState] = useState("all"); const [assignee, setAssignee] = useState("all"); const list = data.tasks.filter((task: any) => task.title.includes(query) && (state === "all" || task.status === state) && (assignee === "all" || task.assigneeMemberId === Number(assignee))); return <div className="entry"><PageHeading title="المهام" description="وش كل الأعمال المسندة حاليًا؟" action={<Button onClick={openTask} className="h-10 gap-2 bg-[#52769F] hover:bg-[#46698F]"><Plus className="size-4" />مهمة جديدة</Button>} /><div className="mb-5 flex flex-wrap gap-3"><div className="relative min-w-52 flex-1"><Search className="absolute right-3 top-2.5 size-4 text-slate-400" /><Input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="ابحث عن مهمة" className="h-9 border-slate-200 bg-white pr-9" /></div><select value={state} onChange={(e) => setState(e.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-sm"><option value="all">كل الحالات</option>{Object.entries(taskStatusLabel).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select><select value={assignee} onChange={(e) => setAssignee(e.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-sm"><option value="all">كل المسؤولين</option>{data.members.map((member: any) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></div><div className="overflow-hidden rounded-xl border border-slate-200 bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-right"><thead className="border-b border-slate-100 bg-[#FCFDFE] text-[11px] text-[#7C8A9A]"><tr><th className="w-12 px-4 py-3" /><th className="px-4 py-3">المهمة</th><th className="px-4 py-3">المسؤول</th><th className="px-4 py-3">المشروع</th><th className="px-4 py-3">الموعد</th><th className="px-4 py-3">الحالة</th></tr></thead><tbody>{list.map((task: any) => { const member = data.members.find((item: any) => item.id === task.assigneeMemberId); const project = data.projects.find((item: any) => item.id === task.projectId); return <tr key={task.id} className="border-b border-slate-100 last:border-0 hover:bg-[#FBFCFE]"><td className="px-4 py-3.5"><button onClick={() => completeTask(task.id)} className={cn("flex size-5 items-center justify-center rounded-md border", task.status === "complete" ? "border-emerald-500 bg-emerald-500 text-white" : "border-slate-300 text-transparent hover:border-[#6C8FB8]")}><Check className="size-3" /></button></td><td className="px-4 py-3.5 text-sm font-medium">{task.title}{task.parentTaskId && <span className="mr-2 text-[10px] text-[#7C8A9A]">مهمة فرعية</span>}</td><td className="px-4 py-3.5"><div className="flex items-center gap-2"><Avatar initials={member?.avatarInitials ?? "—"} color={member?.color} className="size-6 text-[9px]" /><span className="text-xs">{member?.name ?? "—"}</span></div></td><td className="px-4 py-3.5 text-xs text-[#7C8A9A]">{project?.title ?? "غير مرتبط"}</td><td className="px-4 py-3.5 text-xs text-[#7C8A9A]">{dateText(task.dueDate)}</td><td className="px-4 py-3.5"><StatusPill status={task.status} /></td></tr>; })}</tbody></table></div></div></div>; }

function TeamPage({ data, setPage, setMemberId }: any) { const support = data.members.filter((member: any) => member.loadStatus === "loaded" || member.overdueCount > 0); const loadLabel: Record<string, string> = { available: "متاح", busy: "مشغول", loaded: "محمّل" }; const loadClass: Record<string, string> = { available: "bg-emerald-50 text-emerald-700", busy: "bg-amber-50 text-amber-700", loaded: "bg-rose-50 text-rose-700" }; return <div className="entry"><PageHeading title="الفريق" description="مين عليه ضغط ومين متاح؟" /><div className="overflow-hidden rounded-xl border border-slate-200 bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-right"><thead className="border-b border-slate-100 bg-[#FCFDFE] text-[11px] text-[#7C8A9A]"><tr><th className="px-5 py-3.5">العضو</th><th className="px-5 py-3.5">الدور</th><th className="px-5 py-3.5">الأعمال الحالية</th><th className="px-5 py-3.5">حالة الضغط</th><th className="px-5 py-3.5">المهام المتأخرة</th><th /></tr></thead><tbody>{data.members.map((member: any) => <tr key={member.id} onClick={() => { setMemberId(member.id); setPage("member"); }} className="cursor-pointer border-b border-slate-100 last:border-0 hover:bg-[#FBFCFE]"><td className="px-5 py-4"><div className="flex items-center gap-3"><Avatar initials={member.avatarInitials} color={member.color} className="size-8 text-[10px]" /><span className="text-sm font-medium">{member.name}</span></div></td><td className="px-5 py-4 text-xs text-[#7C8A9A]">{member.role}</td><td className="px-5 py-4 text-sm">{member.activeTaskCount}</td><td className="px-5 py-4"><span className={cn("rounded-full px-2.5 py-1 text-[11px] font-medium", loadClass[member.loadStatus])}>{loadLabel[member.loadStatus]}</span></td><td className="px-5 py-4 text-sm">{member.overdueCount || "—"}</td><td className="px-5 py-4"><ChevronLeft className="size-4 text-slate-400" /></td></tr>)}</tbody></table></div></div><section className="mt-6 max-w-3xl rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>يحتاج دعم</SectionTitle>{support.length ? <div className="space-y-3">{support.map((member: any) => <div key={member.id} className="flex items-center gap-3"><Avatar initials={member.avatarInitials} color={member.color} className="size-7 text-[10px]" /><p className="flex-1 text-sm"><b className="font-medium">{member.name}</b><span className="mr-2 text-[#7C8A9A]">لديه عبء مرتفع أو مهام متأخرة</span></p><span className="text-xs text-rose-700">يحتاج متابعة</span></div>)}</div> : <EmptyState title="لا يوجد أعضاء يحتاجون دعمًا حاليًا" />}</section></div>; }

function MemberDetail({ data, memberId, setPage }: any) { const member = data.members.find((item: any) => item.id === memberId) ?? data.members[0]; const current = data.tasks.filter((task: any) => task.assigneeMemberId === member.id && task.status !== "complete"); return <div className="entry max-w-4xl"><button onClick={() => setPage("team")} className="mb-5 flex items-center gap-1 text-sm text-[#647487]"><ArrowRight className="size-4" />الفريق</button><div className="rounded-xl border border-slate-200 bg-white p-6"><div className="flex items-center gap-4"><Avatar initials={member.avatarInitials} color={member.color} className="size-14 text-base" /><div><h1 className="text-xl font-bold">{member.name}</h1><p className="mt-1 text-sm text-[#7C8A9A]">{member.role}</p></div><span className={cn("mr-auto rounded-full px-3 py-1.5 text-xs font-medium", member.loadStatus === "loaded" ? "bg-rose-50 text-rose-700" : member.loadStatus === "busy" ? "bg-amber-50 text-amber-700" : "bg-emerald-50 text-emerald-700")}>{member.loadStatus === "loaded" ? "محمّل" : member.loadStatus === "busy" ? "مشغول" : "متاح"}</span></div></div><div className="mt-5 grid gap-5 md:grid-cols-2"><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>أعماله الحالية</SectionTitle>{current.map((task: any) => <div key={task.id} className="flex items-center justify-between border-b border-slate-100 py-3 last:border-0"><p className="text-sm">{task.title}</p><StatusPill status={task.status} /></div>)}</section><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>هذا الأسبوع</SectionTitle>{current.slice(0, 4).map((task: any) => <div key={task.id} className="flex items-center gap-3 py-3"><span className="size-1.5 rounded-full bg-[#6C8FB8]" /><p className="flex-1 text-sm">{task.title}</p><span className="text-xs text-[#7C8A9A]">{dateText(task.dueDate)}</span></div>)}</section></div></div>; }

function CalendarPage({ data }: any) { const days = Array.from({ length: 31 }, (_, index) => index + 1); const eventsByDay = data.events.reduce((acc: Record<number, any[]>, event: any) => { const day = new Date(event.eventDate).getUTCDate(); (acc[day] ??= []).push(event); return acc; }, {} as Record<number, any[]>); return <div className="entry"><PageHeading title="التقويم" description="متى الأشياء المهمة؟" /><div className="grid gap-5 xl:grid-cols-[1fr_265px]"><section className="overflow-hidden rounded-xl border border-slate-200 bg-white"><div className="border-b border-slate-100 px-5 py-4"><h2 className="font-semibold">أغسطس ٢٠٢٦</h2></div><div className="grid grid-cols-7 border-b border-slate-100 text-center text-[11px] text-[#7C8A9A]">{["أحد", "اثنين", "ثلاثاء", "أربعاء", "خميس", "جمعة", "سبت"].map((day) => <div key={day} className="py-3">{day}</div>)}</div><div className="grid grid-cols-7">{Array.from({ length: 6 }, (_, index) => <div key={`blank-${index}`} className="min-h-24 border-b border-l border-slate-100 bg-[#FCFDFE]" />)}{days.map((day) => <div key={day} className={cn("min-h-24 border-b border-l border-slate-100 p-2", day === 26 && "bg-[#EDF4FA]/45")}><span className={cn("flex size-6 items-center justify-center rounded-full text-xs", day === 26 && "bg-[#6C8FB8] text-white")}>{day}</span><div className="mt-1 space-y-1">{(eventsByDay[day] ?? []).map((event: any) => <button key={event.id} className="w-full truncate rounded border-r-2 border-[#6C8FB8] bg-[#EDF4FA] px-1.5 py-1 text-right text-[10px] text-[#46698F]">{event.title}</button>)}</div></div>)}</div></section><aside className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>القادم</SectionTitle><div className="space-y-4">{data.events.slice(0, 5).map((event: any) => <div key={event.id} className="flex gap-3"><div className="w-9 text-center"><p className="text-sm font-bold text-[#52769F]">{new Date(event.eventDate).getUTCDate()}</p><p className="text-[9px] text-[#7C8A9A]">أغسطس</p></div><div className="min-w-0 border-r border-slate-100 pr-3"><p className="text-sm font-medium">{event.title}</p><p className="mt-1 text-[11px] text-[#7C8A9A]">{event.type === "meeting" ? "اجتماع" : event.type === "delivery" ? "تسليم" : event.type === "launch" ? "إطلاق" : "ورشة"}</p></div></div>)}</div></aside></div></div>; }

function ReportsPage({ data, period, goPeriod }: any) { const completed = data.tasks.filter((task: any) => task.status === "complete").length; const overdue = data.tasks.filter((task: any) => task.status === "overdue").length; const achievement = Math.round((completed / data.tasks.length) * 100); const chart = [{ name: "الأسبوع ١", value: 38 }, { name: "الأسبوع ٢", value: 45 }, { name: "الأسبوع ٣", value: 56 }, { name: "الأسبوع ٤", value: achievement }]; return <div className="entry max-w-5xl"><PageHeading title="التقارير" description="كيف أداء القسم؟" action={<PeriodSelect value={period} onChange={goPeriod} />} /><div className="mb-6 grid gap-3 md:grid-cols-3">{[{ label: "الإنجاز", value: `${achievement}%`, tone: "text-[#52769F]" }, { label: "المتأخر", value: overdue, tone: "text-rose-700" }, { label: "المكتمل", value: completed, tone: "text-emerald-700" }].map((item) => <div key={item.label} className="rounded-xl border border-slate-200 bg-white px-5 py-4"><p className="text-xs text-[#7C8A9A]">{item.label}</p><p className={cn("mt-2 text-2xl font-bold", item.tone)}>{item.value}</p></div>)}</div><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>تطور الإنجاز</SectionTitle><div className="h-64"><ResponsiveContainer width="100%" height="100%"><LineChart data={chart} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: "#7C8A9A", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#7C8A9A", fontSize: 11 }} width={28} /><Tooltip contentStyle={{ borderRadius: 10, border: "1px solid #E6EDF3", fontFamily: "IBM Plex Sans Arabic" }} /><Line type="monotone" dataKey="value" stroke="#6C8FB8" strokeWidth={2.5} dot={{ r: 3, fill: "#6C8FB8" }} /></LineChart></ResponsiveContainer></div></section><section className="mt-5 max-w-3xl rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>ملخص</SectionTitle><div className="space-y-3 text-sm leading-6 text-[#52657A]"><p><TrendingUp className="ml-2 inline size-4 text-emerald-600" />تحسن الإنجاز <strong className="font-semibold text-[#26364A]">٨٪</strong> عن الشهر الماضي.</p><p><Check className="ml-2 inline size-4 text-emerald-600" />انخفضت المهام المتأخرة بمهمتين خلال الفترة.</p><p><AlertTriangle className="ml-2 inline size-4 text-amber-600" />مشروع <strong className="font-semibold text-[#26364A]">منصة الشراكات</strong> يحتاج متابعة.</p></div></section></div>; }

function SettingsPage() { return <div className="entry max-w-3xl"><PageHeading title="الإعدادات" description="إدارة تفضيلات القسم وصلاحيات الوصول." /><div className="rounded-xl border border-slate-200 bg-white p-5"><SectionTitle>الصلاحيات</SectionTitle><div className="divide-y divide-slate-100"><div className="py-4"><p className="text-sm font-semibold">مدير القسم</p><p className="mt-1 text-sm text-[#7C8A9A]">إدارة المشاريع وإسناد المهام واعتماد المخرجات ومشاهدة التقارير.</p></div><div className="py-4"><p className="text-sm font-semibold">عضو الفريق</p><p className="mt-1 text-sm text-[#7C8A9A]">مشاهدة الأعمال المرتبطة به وتحديث حالة مهمته وإضافة تعليق أو مرفق.</p></div></div></div></div>; }

function PresentationMode({ data, period, close }: any) { const completion = Math.round((data.tasks.filter((task: any) => task.status === "complete").length / data.tasks.length) * 100); const priorities = data.tasks.filter((task: any) => task.status !== "complete").slice(0, 5); const attention = data.tasks.filter((task: any) => task.status === "overdue").slice(0, 3); return <div dir="rtl" className="min-h-screen bg-[#F7F9FC] p-7 md:p-12"><button onClick={close} className="absolute left-6 top-6 rounded-lg border border-slate-200 bg-white p-2 text-slate-500"><X className="size-5" /></button><div className="mx-auto max-w-6xl"><p className="text-sm font-semibold text-[#6C8FB8]">وضع العرض · {periodLabels[period as Period]}</p><h1 className="mt-3 text-4xl font-bold tracking-tight md:text-5xl">لوحة تشغيل القسم</h1><div className="mt-12 grid gap-5 lg:grid-cols-[.8fr_1fr_1fr]"><section className="rounded-2xl border border-[#DCE7F2] bg-white p-7"><p className="text-sm text-[#7C8A9A]">إنجاز الفترة</p><p className="mt-4 text-6xl font-bold text-[#52769F]">{completion}%</p><Progress value={completion} className="mt-6 h-2.5 bg-[#EDF4FA] [&>div]:bg-[#6C8FB8]" /></section><section className="rounded-2xl border border-slate-200 bg-white p-7"><h2 className="mb-5 text-lg font-semibold">أولوياتنا</h2>{priorities.map((task: any) => <p key={task.id} className="border-b border-slate-100 py-3 text-sm last:border-0">{task.title}</p>)}</section><section className="rounded-2xl border border-slate-200 bg-white p-7"><h2 className="mb-5 text-lg font-semibold">يحتاج انتباه</h2>{attention.map((task: any) => <p key={task.id} className="border-b border-slate-100 py-3 text-sm text-rose-700 last:border-0">{task.title}</p>)}<div className="mt-5"><h3 className="mb-3 text-sm font-semibold">القادم</h3>{data.events.slice(0, 3).map((event: any) => <p key={event.id} className="py-1.5 text-sm text-[#52657A]">{dateText(event.eventDate)} · {event.title}</p>)}</div></section></div></div></div>; }

function TaskDrawer({ open, setOpen, data, submitting, onSubmit }: any) { const [title, setTitle] = useState(""); const [projectId, setProjectId] = useState(""); const [assigneeId, setAssigneeId] = useState(""); const [dueDate, setDueDate] = useState("2026-08-29"); const [priority, setPriority] = useState("medium"); const submit = (event: React.FormEvent) => { event.preventDefault(); if (!title.trim()) return toast.error("أدخل اسم المهمة"); onSubmit({ title, projectId: projectId ? Number(projectId) : null, assigneeMemberId: assigneeId ? Number(assigneeId) : null, startDate: new Date("2026-08-26T09:00:00"), dueDate: dueDate ? new Date(`${dueDate}T09:00:00`) : null, priority, status: "not_started" }); setTitle(""); setOpen(false); }; return <Sheet open={open} onOpenChange={setOpen}><SheetContent side="left" dir="rtl" className="w-full overflow-y-auto sm:max-w-md"><SheetHeader className="text-right"><SheetTitle>مهمة جديدة</SheetTitle><SheetDescription>أضف المهمة مرة واحدة لتظهر تلقائيًا في الفترات المناسبة.</SheetDescription></SheetHeader><form onSubmit={submit} className="mt-7 space-y-5"><Field label="اسم المهمة"><Input autoFocus value={title} onChange={(e) => setTitle(e.target.value)} placeholder="مثال: مراجعة دليل الاستخدام" /></Field><Field label="المشروع"><select value={projectId} onChange={(e) => setProjectId(e.target.value)} className="form-select"><option value="">غير مرتبط بمشروع</option>{data.projects.map((project: any) => <option key={project.id} value={project.id}>{project.title}</option>)}</select></Field><Field label="المسؤول"><select value={assigneeId} onChange={(e) => setAssigneeId(e.target.value)} className="form-select"><option value="">غير مسند</option>{data.members.map((member: any) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><div className="grid grid-cols-2 gap-3"><Field label="تاريخ البداية"><Input type="date" defaultValue="2026-08-26" /></Field><Field label="الموعد النهائي"><Input type="date" value={dueDate} onChange={(e) => setDueDate(e.target.value)} /></Field></div><Field label="الأولوية"><select value={priority} onChange={(e) => setPriority(e.target.value)} className="form-select">{Object.entries(priorityLabel).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></Field><details className="rounded-lg bg-[#F7F9FC] p-3 text-sm text-[#52657A]"><summary className="cursor-pointer font-medium">خيارات إضافية</summary><p className="mt-3 text-xs leading-6 text-[#7C8A9A]">يمكن إضافة الوصف والمرفقات والمشاركين والمهام الفرعية من صفحة المهمة بعد الحفظ.</p></details><Button disabled={submitting} type="submit" className="h-10 w-full bg-[#52769F] hover:bg-[#46698F]">{submitting ? "جارٍ الحفظ..." : "حفظ المهمة"}</Button></form></SheetContent></Sheet>; }

function ProjectDrawer({ open, setOpen, data, submitting, onSubmit }: any) { const [title, setTitle] = useState(""); const [goalId, setGoalId] = useState(""); const [ownerId, setOwnerId] = useState(""); const [summary, setSummary] = useState(""); const submit = (event: React.FormEvent) => { event.preventDefault(); if (!title.trim() || !ownerId) return toast.error("أدخل اسم المشروع واختر المسؤول"); onSubmit({ title, summary, annualGoalId: goalId ? Number(goalId) : null, ownerMemberId: Number(ownerId), startDate: new Date("2026-08-26T09:00:00"), endDate: new Date("2026-10-30T09:00:00"), status: "planned" }); setTitle(""); setSummary(""); setOpen(false); }; return <Sheet open={open} onOpenChange={setOpen}><SheetContent side="left" dir="rtl" className="w-full overflow-y-auto sm:max-w-md"><SheetHeader className="text-right"><SheetTitle>مشروع جديد</SheetTitle><SheetDescription>يرتبط المشروع بهدف سنوي ويظهر في تقارير وخطط الفترة تلقائيًا.</SheetDescription></SheetHeader><form onSubmit={submit} className="mt-7 space-y-5"><Field label="اسم المشروع"><Input autoFocus value={title} onChange={(e) => setTitle(e.target.value)} placeholder="اسم المشروع" /></Field><Field label="الهدف المرتبط"><select value={goalId} onChange={(e) => setGoalId(e.target.value)} className="form-select"><option value="">بدون هدف مرتبط</option>{data.goals.map((goal: any) => <option key={goal.id} value={goal.id}>{goal.title}</option>)}</select></Field><Field label="المسؤول"><select value={ownerId} onChange={(e) => setOwnerId(e.target.value)} className="form-select"><option value="">اختر المسؤول</option>{data.members.map((member: any) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><div className="grid grid-cols-2 gap-3"><Field label="تاريخ البداية"><Input type="date" defaultValue="2026-08-26" /></Field><Field label="تاريخ النهاية"><Input type="date" defaultValue="2026-10-30" /></Field></div><Field label="وصف مختصر"><textarea value={summary} onChange={(e) => setSummary(e.target.value)} className="min-h-24 w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm outline-none focus:border-[#6C8FB8]" placeholder="وصف مختصر للمشروع" /></Field><Button disabled={submitting} type="submit" className="h-10 w-full bg-[#52769F] hover:bg-[#46698F]">{submitting ? "جارٍ الحفظ..." : "حفظ المشروع"}</Button></form></SheetContent></Sheet>; }

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block"><span className="mb-2 block text-sm font-medium text-[#52657A]">{label}</span>{children}</label>; }
function LoadingShell() { return <div dir="rtl" className="min-h-screen bg-[#F7F9FC] p-8 lg:mr-[272px]"><div className="mx-auto max-w-5xl animate-pulse"><div className="h-4 w-32 rounded bg-slate-200" /><div className="mt-4 h-9 w-64 rounded bg-slate-200" /><div className="mt-10 h-28 max-w-xl rounded-xl bg-white" /><div className="mt-5 grid gap-5 lg:grid-cols-2"><div className="h-80 rounded-xl bg-white" /><div className="h-80 rounded-xl bg-white" /></div></div></div>; }
